import assert from 'node:assert/strict';
import {readFileSync,statSync} from 'node:fs';
import {spawnSync} from 'node:child_process';
import {sourceFingerprint} from './scripts/documentation-lib.mjs';
import {sourceSecretScan} from './scripts/ci/security.mjs';
import {privateRedactionValues} from './scripts/evidence-lib.mjs';
const run=(name,args,options={})=>{const x=spawnSync(name,args,{encoding:'utf8',...options});assert.equal(x.status,0,x.stderr);return x.stdout;};
run('pnpm',['docs:check'],{stdio:'inherit'});
assert.equal(sourceFingerprint(process.cwd()),JSON.parse(readFileSync('docs/validation/runs/RUN-20261010-015.json')).source_fingerprint);
assert.equal(run('git',['diff','--name-only','HEAD','--','apps','packages','scripts','tests','.devcontainer','.github','.vscode','infra','package.json','pnpm-lock.yaml','pnpm-workspace.yaml','toolchain.json','tsconfig.base.json','eslint.config.mjs']).trim(),'');
for(const file of ['.env.local','.local/database.json']){
 const s=statSync(file);assert.equal(s.mode&0o777,0o600);assert.equal(s.uid,1000);run('git',['check-ignore','-q',file]);
}
const ports=new Set([5173,3001,3002]);let tcpRows=0;
for(const file of ['/proc/net/tcp','/proc/net/tcp6']){
 const lines=readFileSync(file,'utf8').trim().split('
');assert(lines[0].includes('local_address'));
 for(const line of lines.slice(1)){const a=line.trim().split(/\s+/);assert(a.length>=10);tcpRows++;if(a[3]==='0A')assert(!ports.has(parseInt(a[1].split(':').at(-1),16)));}
}
assert(tcpRows>0);
run('python3',['-c',"import csv,json,re,subprocess
from pathlib import Path
rows=list(csv.DictReader(Path('docs/vision/requirements.csv').open()))
assert len(rows)==548 and len({r['group_id'] for r in rows})==33
assert sum(r['source_optional']=='true' for r in rows)==20
original=re.findall(r'^\s+\*\s+(.+)$',Path('docs/vision/original_action_items.md').read_text(),re.M)
assert [r['source_text'] for r in rows]==original
assert Path('docs/vision/requirements.csv').read_bytes()==subprocess.check_output(['git','show','335da7edffea40294b8dcf60ae256524432c350b:docs/vision/requirements.csv'])
d=json.loads(Path('docs/vision/dependencies.json').read_text()); assert len(d['packages'])==61
w=Path('docs/plans/2026-10-10-boot-04-decision-worksheet.md').read_text()
claims=re.findall(r'^\| \x60([^\x60]+)\x60 \| ([\d.]+) \| .*? \| Installed \(([^)]+)\) \|$',w,re.M)
assert len(claims)>15
refs=0
for name,version,owners in claims:
 for owner in owners.split(','):
  base=Path('.') if owner.strip()=='root' else Path(owner.strip())
  x=json.loads((base/'package.json').read_text())
  assert any(x.get(k,{}).get(name)==version for k in ['dependencies','devDependencies','peerDependencies']),(name,owner)
  refs+=1
tasks=list(csv.DictReader(Path('docs/vision/initial_backlog.csv').open())); assert len(tasks)==32
assert next(r for r in tasks if r['task_id']=='RULE-01')['implementation_status']=='pending'
assert next(r for r in tasks if r['task_id']=='BOOT-04')['implementation_status']=='decision_worksheet_finalized_director_signoff_recorded_deployment_configuration_pending'
assert round(14.50+0.80+10.46/12,2)==16.17
assert round(25-(14.50+0.80+10.46/12),2)==8.83
print('PASS548 original source texts/unchanged bytes,33 groups/20 optional flags,61 selected dependencies,',len(claims),'installed claims/',refs,'owner references,32 task statuses and dated quote arithmetic. No current-price/capacity certification.')"],{stdio:'inherit'});
sourceSecretScan(process.cwd(),Object.values(privateRedactionValues(process.cwd())));
run('git',['diff','--check','--','.',':(exclude)docs/validation/logs/**'],{stdio:'inherit'});
console.log('PASS unchanged executable/config/dependencies, ignored0600 UID1000 private files, actual TCP rows',tcpRows,'without app listeners, full-history secret checks and formatting.');
